'use strict';
(function(){
const key='poetics-atlas-entry-drafts-v1',h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function webURL(value){try{return ['https:','http:'].includes(new URL(value).protocol);}catch{return false;}}
function createDraft(input){
const text=key=>String(input[key]||'').trim();
if(!text('name')||!text('details')||!text('location'))throw Error('Add a name, details and location. Use “Unverified” if the location is unknown.');
if(!['People','Places','Platforms','Prizes','Publications'].includes(input.category))throw Error('Choose an entry type.');
if(!webURL(text('source')))throw Error('Add a public source link beginning with https:// or http://.');
if(text('image')&&(!webURL(text('image'))||input.imagePermission!=='on'||!text('imageCredit')))throw Error('To include an image, add its public link, credit and reuse permission.');
return {id:'entry-draft-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),name:text('name'),category:input.category,details:text('details'),location:text('location'),state:text('state'),year:text('year'),yearMeaning:text('yearMeaning'),source:text('source'),sourceLocator:text('sourceLocator'),connections:text('connections'),image:text('image'),imageCredit:text('imageCredit'),imagePermission:input.imagePermission==='on',contributor:text('contributor'),createdAt:new Date().toISOString(),status:'Draft — saved on this device; not submitted or published'};
}
window.PoeticsContribute={createDraft,key};
window.renderContribute=function(root){
root.classList.add('atlas-brand');let saved=[];try{const value=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(value))saved=value.filter(d=>d&&typeof d.id==='string'&&typeof d.name==='string'&&['People','Places','Platforms','Prizes','Publications'].includes(d.category));}catch{}
root.innerHTML=`<section class="project-page"><a class="quiet-back" href="#/atlas"> Back to the Atlas</a><p class="quiet-kicker">Help keep the record open</p><h1>Submit an entry.</h1><p class="project-intro">Know a poet, place, platform or competition we should include? Bring its story and a source.</p><p class="submission-notice">This preview saves drafts on your device. Download a draft for editorial review; it is not sent to Vic’Adex or added to the Atlas automatically.</p><form id="entry-form" class="entry-form"><div class="entry-field-pair"><label>Name<input name="name" required maxlength="160" autocomplete="off" placeholder="Name of the person, place or initiative"></label><label>Entry type<select name="category" required><option value="People">Person</option><option value="Places">Place</option><option value="Platforms">Platform / festival / organisation</option><option value="Prizes">Prize / slam / competition</option><option value="Publications">Publication / anthology / journal / album</option></select></label></div><label>Details<textarea name="details" required maxlength="2000" rows="4" placeholder="What is it, and what is its contribution to poetry?"></textarea></label><div class="entry-field-pair"><label>City / location<input name="location" required maxlength="180" placeholder="Ilesa, Online, Nigeria, or Unverified"></label><label>State / FCT<select name="state"><option>Not mapped / nationwide / online</option>${window.PoeticsStateMap.states.map(s=>s.name).sort().map(n=>`<option>${h(n)}</option>`).join('')}</select></label></div><div class="entry-field-pair"><label>Year or period <span>Optional</span><input name="year" maxlength="80" placeholder="2016, circa 2010, or unverified"></label><label>What does that date describe?<select name="yearMeaning"><option>Documented activity</option><option>Source publication</option><option>Founding date stated by the source</option><option>Date unverified</option></select></label></div><label>Public source link<input name="source" type="url" required placeholder="https://…"></label><label>Where in the source is the evidence? <span>Optional</span><input name="sourceLocator" maxlength="300" placeholder="Article date, page, paragraph or video timestamp"></label><label>Connections <span>Optional</span><textarea name="connections" maxlength="1500" rows="3" placeholder="Who organised it? Who performed, judged or won? Which venue hosted it? Include evidence for each connection."></textarea></label><details class="entry-image-fields"><summary>Add a picture</summary><label>Public picture link<input name="image" type="url" placeholder="https://…"></label><label>Picture credit<input name="imageCredit" maxlength="180" placeholder="Photographer / rights holder"></label><label class="entry-checkbox"><input type="checkbox" name="imagePermission">I own this picture or have permission to reuse it here.</label></details><label>Your name <span>Optional attribution</span><input name="contributor" maxlength="160" autocomplete="name"></label><p id="entry-feedback" role="status" aria-live="polite"></p><div class="entry-actions"><button type="submit" class="primary">Save entry draft</button><button type="button" id="download-entry" hidden>Download draft</button></div></form><section class="saved-entry-drafts" aria-label="Drafts saved on this device"><h2>Your saved drafts</h2><div id="saved-entry-list">${savedList()}</div></section></section>`;
function savedList(){return saved.length?saved.slice().reverse().map(d=>`<div><span><b>${h(d.name)}</b><small>${h(d.category)} · ${h(d.year||'Year unverified')} · draft</small></span><button data-draft="${h(d.id)}">Download </button></div>`).join(''):'<p>No entry drafts saved on this device yet.</p>';}
let latest=null;function exportDraft(d){const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindDownloads(){root.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>{const d=saved.find(d=>d.id===b.dataset.draft);if(d)exportDraft(d);});}
bindDownloads();root.querySelector('#download-entry').onclick=()=>latest&&exportDraft(latest);
root.querySelector('#entry-form').onsubmit=e=>{e.preventDefault();const feedback=root.querySelector('#entry-feedback');try{latest=createDraft(Object.fromEntries(new FormData(e.target)));const next=saved.concat(latest);try{localStorage.setItem(key,JSON.stringify(next));saved=next;feedback.textContent='Draft saved on this device. Download it for editorial review; it has not been sent or published.';root.querySelector('#saved-entry-list').innerHTML=savedList();bindDownloads();}catch{feedback.textContent='Device storage is unavailable. Download this draft to keep it; nothing has been sent or published.';}root.querySelector('#download-entry').hidden=false;}catch(error){feedback.textContent=error.message;root.querySelector('#download-entry').hidden=true;}};
};
window.renderPoeticsAbout=function(root){root.classList.add('atlas-brand');root.innerHTML=`<section class="project-page about-poetics"><a class="quiet-back" href="#/atlas"> Back to the Atlas</a><p class="quiet-kicker">A Vic’Adex concept</p><h1>A little room<br>for Nigerian poetry.</h1><p class="project-intro">Poetics brings people, places, platforms, prizes and publications into view—and follows the connections between them.</p><div class="about-project-copy"><h2>The Atlas</h2><p>Explore Nigeria through its poetry communities. Find a person, follow a platform, discover a gathering, or trace a competition. Every record carries sources, documented years and the questions still open.</p><h2>The Games</h2><p>A fictional poetry world where you can write, perform and build a creative life. Its characters and events belong to the simulation; they are kept separate from the historical Atlas.</p><h2>Activity and evidence</h2><p>Active means reviewed organising activity within 12 months or a confirmed upcoming edition. Inactive requires an explicit closure or suspension. Historical identifies documented past initiatives or completed one-off events. Otherwise the status remains unverified.</p><p>Source confirmed covers the stated claim. Report supported means a published report was read; Archive supported means a preserved source was reviewed. Verification pending entries remain leads. Activity dates link to evidence in each profile.</p><h2>A living directory</h2><p>This is an evolving record, not a complete census. A source may announce an event, recall one, or report its result. Dates and relationships keep that distinction visible. Pictures remain credited, with placeholders where reuse has not been cleared.</p><p>Missing a name, place or piece of history? Help us bring it into the record.</p><a class="btn" href="#/submit">Submit an entry </a><p class="about-parent">Part of the Vic’Adex and 60 Seconds Poetry ecosystem.</p></div></section>`;};
})();
